#!/usr/bin/env python3
"""Generate the iOS prefix index from the pinned engine 0.9.5 emoticon source."""
import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
SOURCE = ROOT / "Tools/Emoticons/emoticons.json"
OUTPUT = ROOT / "Shared/Sources/Engine/EmoticonRules.swift"
data = SOURCE.read_bytes()
rules = {}
for group in json.loads(data):
    for alias in group["emoticons"]:
        assert alias and alias.isascii() and alias not in rules
        rules[alias] = group["emoji"]

lines = [
    "// Generated by Tools/Emoticons/generate_swift.py. Do not edit the table.",
    "// Engine 0.9.5 canonical aliases; wooorm/emoticon 4.1.0 (MIT).",
    "// License and pinned source: Tools/Emoticons/.",
    "// Source SHA256: " + hashlib.sha256(data).hexdigest(),
    "import Foundation", "", "enum EmoticonRules {",
    "    static let aliases: [String: String] = [",
]
for alias, emoji in sorted(rules.items()):
    lines.append(f"        {json.dumps(alias)}: {json.dumps(emoji, ensure_ascii=False)},")
lines += [
    "    ]", "",
    f"    static let maximumLength = {max(map(len, rules))}",
    "    private static let prefixes: Set<String> = Set(aliases.keys.flatMap { alias in",
    "        (1...alias.count).map { String(alias.prefix($0)) }",
    "    })", "",
    "    static func isPrefix(_ input: String) -> Bool {",
    "        input.utf8.count <= maximumLength && prefixes.contains(input)",
    "    }", "",
    "    /// Bangla digit keys can finish ASCII faces, e.g. < + ৩ becomes <3.",
    "    /// Outside an eligible prefix the normal numeral behavior is unchanged.",
    "    static func canonicalKeys(_ input: String) -> String {",
    "        String(input.unicodeScalars.map { scalar -> Character in",
    "            if (0x09E6...0x09EF).contains(scalar.value) {",
    "                return Character(UnicodeScalar(scalar.value - 0x09E6 + 0x30)!)",
    "            }",
    "            return Character(scalar)",
    "        })",
    "    }", "",
    "    /// Only actual token boundaries authorize replacement. Slash, digits and",
    "    /// operators can extend a URL or expression and must keep the literal.",
    "    static func isCommitBoundary(_ input: String) -> Bool {",
    '        [".", ",", "!", "?", "।", " ", "\\n", "\\t"].contains(input)',
    "    }", "}", "",
]
OUTPUT.write_text("\n".join(lines))
